function frame(ts){let dt=Math.min(.04,(ts-last)/1000||0);last=ts;elapsed+=dt;if(game.started&&!game.over){game.battleTime+=dt;game.dodgeCooldown=Math.max(0,game.dodgeCooldown-dt);if(game.phase==='ready'){game.timer+=dt;if(game.timer>1.1){beginEnemyTurn()}}else if(game.phase==='windup'){game.timer-=dt;if(game.timer<=0)enemyHit()}else if(game.phase==='recover'){game.timer-=dt;if(game.timer<=0){game.phase='ready';game.timer=0;setStatus('YOUR OPENING','Strike before the next attack')}}else if(game.phase==='playerAttack'){game.timer-=dt;if(game.timer<=0){game.phase='ready';game.timer=0;game.timer=-.35;setStatus('YOUR OPENING','Read the enemy and strike')}}}
ctx.save();if(shake>0){ctx.translate(rand(-shake,shake),rand(-shake,shake));shake*=Math.pow(.02,dt);if(shake<.15)shake=0}drawBackground(elapsed);let base=H*.82,scale=Math.min(H/760,W/1200)*1.12;scale=clamp(scale,.62,1.08);drawFighter(W*.29,base,scale,false,elapsed);drawFighter(W*.71,base,scale,true,elapsed);drawEffects(dt);if(game.parryFlash>0)game.parryFlash-=dt;ctx.restore();requestAnimationFrame(frame)}requestAnimationFrame(frame);
updateHud();
